def _recorder_contracts(result: dict[str, Any], assets: dict[str, bytes], path: Any,
                        opened: dict[str, Any], *, installed_root: Path,
                        main_root: Path, aux_root: Path) -> None:
    """Bind interpreted recorder flows to shared, exact-source proofs once."""
    contracts = copy.deepcopy(RECORDER_CONTRACTS)
    specs = contracts.pop("sources")
    javascript = contracts.pop("javascript_sources")
    sources = {source["id"]: source for source in result["sources"]}
    evidence_ids = {item["id"] for item in result["evidence"]}
    decoder_tokens = {row["methoddef_token"] for row in contracts["DDR_decoders"]["bindings"]}
    for spec in specs:
        p = path(spec["path"])
        if sha256_file(p) != spec["sha256"]:
            raise ValueError(f"recorder source drift: {spec['id']}")
        source = sources.get(spec["id"])
        if source is None:
            source = {"id": spec["id"], "path": p.resolve().relative_to(REPO_ROOT).as_posix(),
                      "sha256": spec["sha256"], "size": p.stat().st_size,
                      "representation": "exact installed PE"}
            for component_root, installed_prefix in ((main_root, "GTSPlus"), (aux_root, "")):
                if p.is_relative_to(component_root):
                    original = installed_root / installed_prefix / p.relative_to(component_root)
                    source["qualification"] = qualify_recovered_source(p, original, component_root=component_root)
                    source["representation"] = "qualified materialized PE"
                    result["evidence"].append({"id": spec["id"] + ".qualification", "source": spec["id"],
                        "kind": "recovered-source-qualification", **source["qualification"]})
                    break
            result["sources"].append(source)
            sources[spec["id"]] = source
        elif source["sha256"] != spec["sha256"]:
            raise ValueError(f"recorder shared source mismatch: {spec['id']}")
        if not spec["methods"]:
            if "module_mvid" in spec:
                source["module_mvid"] = spec["module_mvid"]
            continue
        admission_id = spec["id"] + ".admission"
        if admission_id not in evidence_ids:
            admission = validate_managed_bodies(p)
            result["evidence"].append({"id": admission_id, "source": spec["id"],
                                      "kind": "managed-body-admission", **admission})
            evidence_ids.add(admission_id)
        else:
            admission = next(item for item in result["evidence"] if item["id"] == admission_id)
        if admission["module_mvid"] != spec["module_mvid"]:
            raise ValueError(f"recorder module drift: {spec['id']}")
        source["module_mvid"] = admission["module_mvid"]
        pe = opened.get(spec["path"])
        owns_pe = pe is None
        if owns_pe:
            pe = _open(p)
        try:
            identities = {row["methoddef_token"]: row for row in pe._gts_method_identities["methods"]}
            proof = {"id": "persistence.rm.module." + spec["id"].removeprefix("persistence."),
                     "source": spec["id"], "kind": "selected-managed-method-proofs",
                     "identity_scope": "sha256:" + spec["sha256"] + ":module:" + spec["module_mvid"],
                     "identity_rule": "identity_scope + ':' + TypeDef/MethodDef token; nested ownership stored once per selected type",
                     "branch_coordinates": "byte offsets relative to first IL opcode; targets use the same coordinate",
                     "types": {}, "methods": {}}
            for token, expected in spec["methods"].items():
                identity = identities[token]
                for field in ("name", "typedef_token", "signature_hex", "rva", "impl_flags"):
                    if field in expected and identity[field] != expected[field]:
                        raise ValueError(f"recorder MethodDef identity drift: {spec['id']}:{token}:{field}")
                row = pe.net.mdtables.MethodDef.rows[int(token, 16) - 0x06000001]
                method = {key: identity[key] for key in ("typedef_token", "name", "signature_hex", "rva", "impl_flags", "flags")}
                proof["types"][identity["typedef_token"]] = identity["full_nested_name"]
                if "body" in expected:
                    body = _body(pe, row)
                    actual_pin = _method_pin(row, body)
                    if (actual_pin["body_sha256"], actual_pin["body_size"]) != (expected["body"]["sha256"], expected["body"]["size"]):
                        raise ValueError(f"recorder IL body drift: {spec['id']}:{token}")
                    method["body"] = expected["body"]
                    # Decoder recipes already retain every typed conditional edge; do not duplicate them.
                    if spec["id"] != "persistence.src24" or token not in decoder_tokens:
                        instructions = body.instructions
                        start = instructions[0].offset if instructions else 0
                        branches = []
                        for ins in instructions:
                            opcode = str(ins.opcode)
                            if opcode.startswith(("br", "beq", "bne", "ble", "blt", "bge", "bgt", "switch", "leave")):
                                targets = ins.operand if isinstance(ins.operand, list) else [ins.operand]
                                if all(isinstance(target, int) for target in targets):
                                    branches.append([ins.offset - start, opcode, [target - start for target in targets]])
                        if branches:
                            method["branches"] = branches
                else:
                    method["implementation"] = "CLR-runtime delegate" if identity["impl_flags"] & 3 == 3 else "metadata-declared non-IL boundary"
                proof["methods"][token] = method
            result["evidence"].append(proof)
        finally:
            if owns_pe:
                pe.close()
    for spec in javascript:
        raw = assets[spec["member"]]
        text = raw.decode("utf-8-sig")
        if hashlib.sha256(text.encode("utf-8")).hexdigest() != spec["sha256_utf8"]:
            raise ValueError(f"recorder authenticated member drift: {spec['member']}")
        result["evidence"].append({"id": spec["id"], "source": "persistence.src40",
            "kind": "authenticated-gui-member", "locator": spec["member"],
            "raw_member_sha256": hashlib.sha256(raw).hexdigest(),
            "normalized_utf8_sha256": spec["sha256_utf8"],
            "normalization": "UTF-8 after utf-8-sig decoding; member bytes and normalized text are not conflated",
            "characters": len(text)})
    crypto = contracts["native_crypto"]
    crypto_source = sources[crypto["source"]]
    pe = pefile.PE(str(path(crypto_source["path"])))
    try:
        for span in crypto["spans"]:
            raw = pe.get_data(int(span["rva"], 0), span["size"])
            if hashlib.sha256(raw).hexdigest() != span["sha256"]:
                raise ValueError(f"recorder native crypto span drift: {span['name']}")
        for item in crypto["fixed_data"]:
            raw = pe.get_data(int(item["rva"], 0), item["width"])
            if raw.hex().lower() != item["hex"].lower() or hashlib.sha256(raw).hexdigest() != item["sha256"]:
                raise ValueError(f"recorder crypto fixed-data drift: {item['rva']}")
    finally:
        pe.close()
    result["evidence"].append({"id": "persistence.rm.native_crypto", "source": crypto["source"],
        "kind": "contiguous-native-spans-and-fixed-data", "spans": crypto.pop("spans"),
        "fixed_data": crypto.pop("fixed_data")})
    for key, target in (("display_tables", "recorder_display_tables"),
                        ("image_parameter_tables", "recorder_image_parameter_tables"),
                        ("DDR_decoders", "recorder_DDR_decoders"),
                        ("VDAS_log_bindings", "recorder_VDAS_log_bindings")):
        result["formats"][target] = contracts.pop(key)
    result["states"].extend(contracts.pop("states"))
    contract_by_id = {
        contract["id"]: contract
        for family in ("managed", "support", "frontend", "saved_history")
        for contract in contracts[family]
    }
    available_evidence = {item["id"] for item in result["evidence"]}
    for name, before, after, trigger, action, contract_id in contracts.pop("transitions"):
        proofs = contract_by_id[contract_id]["proof"]
        references = list(dict.fromkeys(
            proof if isinstance(proof, str) else proof["evidence"]
            for proof in proofs
        ))
        if not references or any(reference not in available_evidence for reference in references):
            raise ValueError(f"recorder transition evidence missing: {contract_id}")
        result["transitions"].append({
            "id": "persistence." + name, "from": before, "to": after,
            "trigger": trigger, "action": action, "contract": contract_id,
            "evidence": references,
        })
    result["coverage"]["recorder_lifecycle"] = {
        "managed_contracts": len(contracts["managed"]), "support_contracts": len(contracts["support"]),
        "frontend_contracts": len(contracts["frontend"]), "saved_history_contracts": len(contracts["saved_history"]),
        "legacy_recorder_families": list(contracts["legacy_recorder_families"]),
        "native_serialization_contracts": len(contracts["native_serialization"]["contracts"]),
        "proof_policy": "One complete admission summary per actual managed source; selected immutable identities/body/signature/branch proofs only. Recovery validator owns exhaustive unrelated row admission."
    }
    result["recorder_contracts"] = contracts

def _operand(pe: Any, operand: Any) -> str:
    if hasattr(operand, "table"):
        resolved = resolve_token(pe, operand)
        if hasattr(resolved, "Method"):
            operand = resolved.Method.row
    text = format_operand(pe, operand)
    if " object at " in text:
        return "<generic-type>::" + text.split("::", 1)[1] if "::" in text else "<generic-token>"
    return text


def build(*, installed_root: Path = DEFAULT_INSTALLED, main_root: Path = DEFAULT_MAIN,
          aux_root: Path = DEFAULT_AUX) -> dict[str, Any]:
    """Re-extract decisive IL/byte/JS anchors and reject source or body drift."""
    def path(value: str) -> Path:
        original = REPO_ROOT / value
        for old, new in ((DEFAULT_INSTALLED, installed_root), (DEFAULT_MAIN, main_root), (DEFAULT_AUX, aux_root)):
            if original.is_relative_to(old):
                return new / original.relative_to(old)
        return original

    assets = decode_gui(installed_root / "GTSPlusGUI/gts.gui",
                        aux_root / "ContentServer/GtsPlus-CM.dll",
                        aux_root / "ContentServer/CryptgraphResource.dll",
                        aux_root / "ContentServer/CryptgraphCommon.dll",
                        installed_root / "ContentServer/dist.crt")
    publication_js = []
    for suffix, marker, finding in _PUBLICATION_JS:
        member = "js/gts/common/stored_data_manager.js"
        text = assets[member].decode("utf-8-sig")
        start = text.index(marker)
        end = text.find("StoredDataManager.prototype.", start + len(marker))
        function = text[start:end if end >= 0 else len(text)]
        result_body = {"character_offset": start, "text": marker,
                       "character_length": len(function),
                       "sha256_utf8": hashlib.sha256(function.encode()).hexdigest()}
        # Evidence is emitted below after the result schema is initialized.
        publication_js.append({"id": "persistence." + suffix, "source": "persistence.src42",
            "kind": "authenticated-javascript-function", "locator": member,
            "anchors": [result_body], "finding": finding})
    sources = copy.deepcopy(EXPECTED_SOURCES)
    source_by_id = {source["id"]: source for source in EXPECTED_SOURCES}
    for source in sources:
        if "archive_member" in source:
            raw = assets[source["archive_member"]]
            actual_size, actual_hash = len(raw), hashlib.sha256(raw).hexdigest()
        else:
            p = path(source["path"])
            actual_size, actual_hash = p.stat().st_size, sha256_file(p)
            component_root = next((root for root in (main_root, aux_root) if p.is_relative_to(root)), None)
            if component_root is not None:
                original = path(source_by_id[source["original_source"]]["path"])
                source["qualification"] = qualify_recovered_source(p, original, component_root=component_root)
                source["sha256"], source["size"] = actual_hash, actual_size
            source["path"] = p.resolve().relative_to(REPO_ROOT).as_posix()
        if (actual_size, actual_hash) != (source["size"], source["sha256"]):
            raise ValueError(f"persistence source drift: {source['id']}")

    result = copy.deepcopy(LIFECYCLE)
    result["sources"] = sources
    result["evidence"] = [{"id": source["id"] + ".qualification", "source": source["id"],
                           "kind": "recovered-source-qualification", **source["qualification"]}
                          for source in sources if "qualification" in source]
    result["evidence"].extend(publication_js)
    opened: dict[str, Any] = {}
    for spec in METHODS:
        if spec["path"] not in opened:
            p = path(spec["path"])
            admission = validate_managed_bodies(p)
            opened[spec["path"]] = _open(p)
            result["evidence"].append({"id": spec["source"] + ".admission", "source": spec["source"],
                "kind": "managed-body-admission", **admission})
        pe = opened[spec["path"]]
        rva = spec.get("method_rva", spec["pin"]["rva"])
        owner = spec["type"].replace("/", "+")
        identity, = [identity for identity in pe._gts_method_identities["methods"]
                     if identity["name"] == spec["method"] and identity["rva"] == rva
                     and (identity["full_nested_name"] == owner
                          or identity["full_nested_name"].endswith(("." + owner, "+" + owner)))]
        row = pe.net.mdtables.MethodDef.rows[int(identity["methoddef_token"], 16) - 0x06000001]
        body = _body(pe, row)
        instructions = body.instructions
        pin = _method_pin(row, body)
        if pin != spec["pin"]:
            raise ValueError(f"persistence IL drift: {spec['evidence']}")
        anchors, branches = [], []
        for ins in instructions:
            op = str(ins.opcode)
            operand = _operand(pe, ins.operand)
            if op.startswith(("brfalse", "brtrue", "beq", "bne", "ble", "blt", "bge", "bgt", "switch")) and isinstance(ins.operand, (int, list)):
                branches.append({"offset": ins.offset, "opcode": op, "target": ins.operand})
            if " object at " in operand:
                continue
            if any(term in operand for term in (
                "System.IO.", "GTSPlusArchiver", "Delete", "Process::", "OnLoadVDas",
                "SaveEachComm", "CloseConnect", "StopTimer", "SerializeObject", "CreateEntry",
                "TrimSave", "TrimFuncData", "WriteFuncData", "CheckApi", "GetLicense", "ProcessExit")):
                anchors.append({"offset": ins.offset, "opcode": op, "operand": operand})
        if not anchors:
            anchors = [{"offset": ins.offset, "opcode": str(ins.opcode),
                        "operand": _operand(pe, ins.operand)} for ins in instructions
                       if str(ins.opcode) in ("call", "callvirt", "ldstr")
                       and " object at " not in _operand(pe, ins.operand)]
        if spec.get("context_terms"):
            selected: dict[int, Any] = {}
            for index, ins in enumerate(instructions):
                if any(term in _operand(pe, ins.operand) for term in spec["context_terms"]):
                    for neighbor in instructions[max(0, index - 2):index + 4]:
                        selected[neighbor.offset] = neighbor
            anchors = [{"offset": ins.offset, "opcode": str(ins.opcode),
                        "operand": _operand(pe, ins.operand)} for ins in selected.values()]
        result["evidence"].append({"id": spec["evidence"], "source": spec["source"],
            "kind": "managed-il", "locator": identity["full_nested_name"] + "::" + identity["name"],
            "identity": identity,
            "pin": pin, "anchors": anchors[:48] if spec.get("context_terms") else anchors[:10],
            "branches": branches[:12], "finding": spec["finding"]})

    # Exhaust the shipped converter closure, not just keyword-bearing methods.
    closure_graph = []
    for spec in CSV_CLOSURE:
        p = path(spec["path"])
        admission_id = spec["source"] + ".admission"
        if not any(item["id"] == admission_id for item in result["evidence"]):
            admission = validate_managed_bodies(p)
            result["evidence"].append({"id": admission_id, "source": spec["source"],
                                      "kind": "managed-body-admission", **admission})
        census = inspect_managed_bodies(p)
        pe = opened[spec["path"]] if spec["path"] in opened else _open(p)
        edges, count = [], 0
        for identity in census["methods"]:
            if identity["implementation"] != "il":
                continue
            row = pe.net.mdtables.MethodDef.rows[int(identity["methoddef_token"], 16) - 0x06000001]
            owner = pe.net.mdtables.TypeDef.rows[int(identity["typedef_token"], 16) - 0x02000001]
            count += 1
            for ins in _body(pe, row).instructions:
                if str(ins.opcode).startswith(("call", "newobj", "ldftn")):
                    edges.append({"type": type_name(owner), "method": str(row.Name),
                                  "rva": row.Rva, "offset": ins.offset,
                                  "opcode": str(ins.opcode), "target": _operand(pe, ins.operand)})
        digest = hashlib.sha256(json.dumps(edges, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
        relevant = [edge for edge in edges if any(term in edge["target"] for term in CSV_CALL_TERMS)]
        closure_graph.append({"source": spec["source"], "component": Path(spec["path"]).name,
                              "method_bodies": count, "callsite_sha256": digest, "relevant_calls": relevant})
        if spec["path"] not in opened:
            pe.close()
    if closure_graph != CSV_CALLGRAPH:
        raise ValueError("CSV receiver/task cancellation callgraph drift")
    result["evidence"].append({
        "id": "persistence.csv_cancellation_closure", "source": "persistence.src18",
        "kind": "exhaustive-managed-callgraph", "locator": "GTSPlusCSVConverter/* (10 managed assemblies)",
        "components": closure_graph, "method_bodies": sum(item["method_bodies"] for item in closure_graph),
        "finding": "All884 materialized method bodies inspected. No RelayData.CommandId/GuiRelayMsg read, relay-event subscription, or conversion-task cancellation-token edge. Only Websocket.dll has cancellation calls, for connection deadline; actual send/receive use CancellationToken.None. Request-response reads also occur for translation during conversion; unsolicited99 may remain unread or be consumed as an ordinary response, never dispatched as task cancellation."
    })

    for spec in NATIVE_SPANS:
        pe = pefile.PE(str(path(spec["path"])))
        pin = spec["pin"]
        if hashlib.sha256(pe.get_data(pin["rva"], pin["size"])).hexdigest() != pin["sha256"]:
            raise ValueError(f"persistence native span drift: {spec['evidence']}")
        for anchor in spec["anchors"]:
            expected = bytes.fromhex(anchor["bytes"])
            if pe.get_data(anchor["va"] - pe.OPTIONAL_HEADER.ImageBase, len(expected)) != expected:
                raise ValueError(f"persistence branch-byte drift: {spec['evidence']}")
        result["evidence"].append({"id": spec["evidence"], "source": spec["source"],
            "kind": "native-bytes-and-decompilation", "locator": spec["locator"],
            "pin": pin, "anchors": spec["anchors"], "finding": spec["finding"]})

    for spec in JAVASCRIPT:
        text = assets[spec["member"]].decode("utf-8-sig")
        for anchor in spec["anchors"]:
            start = anchor["character_offset"]
            if text[start:start + len(anchor["text"])] != anchor["text"]:
                raise ValueError(f"persistence JavaScript control-flow drift: {spec['id']}")
        result["evidence"].append({"id": spec["id"], "source": spec["source"],
            "kind": "authenticated-javascript-control-flow", "locator": spec["member"],
            "anchors": spec["anchors"], "finding": spec["finding"]})

    # Decrypt only shipped application configuration; no account data is read.
    decoded = decrypt_file(installed_root / "GTSPlus/Env/ABSystem.yml",
                           installed_root / "GTSPlus/Env/GTSPlus.pp",
                           main_root / "bin/GtsPlus-CM.dll", key_type=2)
    if hashlib.sha256(decoded).hexdigest() != CONFIGURATIONS["collector"]["plaintext_sha256"]:
        raise ValueError("collector decoded policy drift")
    xml = ET.parse(installed_root / "GTSPlusTSEConverter/TSEConverter.exe.config")
    policy = {node.attrib["key"]: node.attrib["value"] for node in xml.findall("./appSettings/add")}
    expected = {key: value for key, value in CONFIGURATIONS["tse"].items() if key != "source"}
    if policy != expected:
        raise ValueError("legacy TSE converter policy drift")
    result["configurations"] = copy.deepcopy(CONFIGURATIONS)
    result["evidence"].extend([
        {"id": "persistence.collector_config", "source": CONFIGURATIONS["collector"]["source"],
         "kind": "authenticated-config", "locator": "ABSystem.yml:error-report",
         "plaintext_sha256": CONFIGURATIONS["collector"]["plaintext_sha256"],
         "limits": CONFIGURATIONS["collector"]["limits"],
         "finding": "Shipped action10000/communication3000 entry bounds; configured1000ms interval is used by communication writer, action is size/event-driven;10MiB and5file rotation; trace history4. No user log contents are read."},
        {"id": "persistence.tse_config", "source": CONFIGURATIONS["tse"]["source"],
         "kind": "xml-config", "locator": "appSettings", "policy": policy,
         "finding": "Legacy converter accepts TSE, uses180_Template.csv, explicitly skips named PCS/RoB/MIL/fuel/oscilloscope data sections."},
    ])
    # Detached VM has no process, filesystem or network objects.
    node = ("const vm=require('vm'),fs=require('fs');const c={};vm.createContext(c);"
            "vm.runInContext(fs.readFileSync(0,'utf8'),c,{timeout:10000});"
            "console.log(JSON.stringify({extension:c.StoredData.TSE_EXTENSION,"
            "json:c.StoredData.JsonFile,hash:c.UserSaveData.HandleFile,version:c.StoredData.FORMAT_VERSION}));")
    run = subprocess.run(["node", "-e", node], input=assets["js/gts/common/constants.js"],
                         capture_output=True, check=True, timeout=15)
    current_constants = json.loads(run.stdout)
    if current_constants != CONSTANTS:
        raise ValueError("saved-session runtime constant drift")
    result["formats"] = {"current_gtse": current_constants, "established_contracts": {
        "gtse_compression": _compression_contract(aux_root / "GTSPlusTSEConverter/TseCompression.dll"),
        "ring": _ring_contract(aux_root / "GTSPlusTSEConverter/RingBufferParser.dll"),
        "vdas": _diag_contract(main_root / "bin/GTSPlusDiagAdaptMng.dll"),
        "vdas_archive": _archiver_contract(main_root / "bin/GTSPlusArchiver.dll"),
    }}
    _recorder_contracts(result, assets, path, opened, installed_root=installed_root,
                        main_root=main_root, aux_root=aux_root)
    for pe in opened.values():
        pe.close()
    return result


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--installed-root", type=Path, default=DEFAULT_INSTALLED)
    parser.add_argument("--main-root", type=Path, default=DEFAULT_MAIN)
    parser.add_argument("--aux-root", type=Path, default=DEFAULT_AUX)
    parser.add_argument("--out", type=Path, default=DEFAULT_OUT)
    args = parser.parse_args()
    value = build(installed_root=args.installed_root, main_root=args.main_root, aux_root=args.aux_root)
    args.out.parent.mkdir(parents=True, exist_ok=True)
    args.out.write_text(json.dumps(value, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    print(f"wrote {args.out.relative_to(REPO_ROOT) if args.out.is_relative_to(REPO_ROOT) else args.out}")


if __name__ == "__main__":
    main()
